use vstd::prelude::*;

verus! {
    fn bitwise_and(a: Vec<u8>, b: Vec<u8>) -> (result: Vec<u8>)
        requires
            a.len() == b.len(),
        ensures
            result.len() == a.len(),
            forall |i: usize| i < result.len() ==> result[i] == a[i] & b[i],
    {
        let n = a.len();
        let mut res: Vec<u8> = Vec::with_capacity(n);
        let mut i: usize = 0;
        while i < n
            invariant
                i <= n,
                res.len() == i,
                forall |j: usize| j < i ==> res[j] == a[j] & b[j],
            decreases n - i,
        {
            let ai = a[i];
            let bi = b[i];
            let ri = ai & bi;
            res.push(ri);
            i = i + 1;
        }
        res
    }
}

